/**
 * The sidebar service mark.
 *
 * Ruling 1: bundle the export PNGs — assets are not runtime dependencies. BUT
 * the PNGs are not in the design handoff: both design bundles ship four files
 * and no `icons/` folder, and the export itself is a hybrid (a PNG for eight
 * services, a text glyph for three). See the finding in the Step 2 report.
 *
 * So this renders:
 *   - the glyph, for the services the export marks with one (aria-hidden — the
 *     label is the accessible name);
 *   - the PNG from public/icons/, ONLY when the asset is actually present
 *     (PRESENT_ICONS, generated by tool/generate-icons.ts). No broken image
 *     ships, and the moment the real PNGs are dropped into public/icons/ and
 *     `pnpm run generate` is re-run, they appear.
 *   - otherwise, a reserved empty slot, so the row height and label alignment
 *     match a service that does have a mark. The label carries wayfinding until
 *     the assets arrive.
 *
 * B13 (glyph-versus-named-icon) recurs only for the SEVEN SEVERITY shapes, where
 * the mark is meaning; a service icon is identity, so a missing one degrades to
 * its label without loss of meaning.
 */

import { PRESENT_ICONS } from '../data/icons.g.ts';
import type { ServiceDef } from '../data/services.ts';

export function ServiceIcon({ service, active }: { service: ServiceDef; active: boolean }) {
  const cls = `pemo-service-icon${active ? ' pemo-service-icon--active' : ''}`;

  if (service.glyph) {
    return <span className={cls} data-icon-kind="glyph" aria-hidden="true">{service.glyph}</span>;
  }

  if (service.iconName && (PRESENT_ICONS as readonly string[]).includes(service.iconName)) {
    return (
      <span className={cls} data-icon-kind="image" aria-hidden="true">
        <img className="pemo-service-icon__img" src={`/icons/${service.iconName}.png`} alt="" />
      </span>
    );
  }

  // Asset declared by the export but not present in the handoff. Reserve the slot.
  return <span className={cls} data-icon-kind="reserved" aria-hidden="true" />;
}
